  return 1;
}
function investorBand(txt) {
  const t = s(txt).toLowerCase(); const h = [];
  if (/pre-?\s*seed|preseed/.test(t)) { h.push(0); }
  if (/\bseed\b/.test(t.replace(/pre-?\s*seed/g, ''))) { h.push(1); }
  if (/pilot|traction|early|pre-?\s*series[\s-]*a/.test(t)) { h.push(2); }
  if (/series[\s-]*a\b/.test(t)) { h.push(3); }
  if (/series[\s-]*[b-e]\b|series[\s-]*a\s*[\/&,]\s*b|growth|late|pre-?\s*ipo|onwards|and above/.test(t)) { h.push(4); }
  if (!h.length) { return null; }
  return { lo: Math.min.apply(null, h), hi: Math.max.apply(null, h) };
