function chequeRange(txt) {
  const t = s(txt).replace(/,/g, '').toLowerCase(); if (!t) { return null; }
  const usd = /\$|usd/.test(t);
  const re = /(\d+(?:\.\d+)?)\s*(crores?|cr|million|mn|m|k|lakhs?|lacs?)?(?![a-z])/g;
  const tok = []; let m;
  while ((m = re.exec(t)) !== null) { tok.push({ v: parseFloat(m[1]), u: m[2] || '' }); }
  if (!tok.length) { return null; }
  for (let i = tok.length - 2; i >= 0; i--) { if (!tok[i].u && tok[i + 1].u) { tok[i].u = tok[i + 1].u; } }
  const vals = [];
  for (const k of tok) { const u = k.u || (usd ? 'm' : 'cr'); let cr;
    if (/^cr/.test(u)) { cr = k.v; } else if (/^la/.test(u)) { cr = k.v / 100; }
    else if (u === 'k') { cr = usd ? k.v * 0.0085 : k.v / 10000; } else { cr = usd ? k.v * 8.5 : k.v / 10; }
    if (cr > 0) { vals.push(cr); } }
  if (!vals.length) { return null; }
  let lo = Math.min.apply(null, vals), hi = Math.max.apply(null, vals);
  if (/minimum|\bmin\b|onwards|above|\+/.test(t)) { hi = Infinity; }
  if (vals.length === 1 && /up\s*to|upto|\bmax/.test(t)) { lo = 0; }
